head.script:
scwin.onpageload = function() {

};

scwin.trigger1_onclick = function (e) {
    var value = multiselect1.getValue();
    output1.setValue(value)
};
scwin.trigger3_onclick = function (e) {
    var value = multiselect2.getValue();
    output2.setValue(value)
};

scwin.multiselect1_onviewchange = function (e) {
    scwin.trigger1_onclick();
};
scwin.multiselect2_onviewchange = function (e) {
    scwin.trigger3_onclick();
};

	scwin.setSimulateDown = function(id) {
		scwin.simulateWrapper('#'+id, 'key-combo', {
			combo: 'down-arrow'
		});
	}
	scwin.setSimulateUp = function(id) {
		scwin.simulateWrapper('#'+id, 'key-combo', {
			combo: 'up-arrow'
		});
	}	
	scwin.setSimulateEnter = function(id) {
		scwin.simulateWrapper('#'+id, 'key-combo', {
			combo: 'ENTER'
		});
	}	
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}

	scwin.checkVal = function(checkVal) {
		return WebSquare.wUnit.getDomById('output2').innerText == checkVal;
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('multiselect2_li_item_0').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal('1')", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("set", "scwin.setSimulateDown('multiselect2_li_item_0')");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("set", "scwin.setSimulateDown('multiselect2_li_item_1')");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("set", "scwin.setSimulateDown('multiselect2_li_item_2')");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("set", "scwin.setSimulateEnter('multiselect2_li_item_3')");
		WebSquare.wUnit.addCommand('pause', '500');				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal('4')", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("set", "scwin.setSimulateUp('multiselect2_li_item_3')");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("set", "scwin.setSimulateUp('multiselect2_li_item_2')");
		WebSquare.wUnit.addCommand('pause', '500');		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulateEnter('multiselect2_li_item_1')");
		WebSquare.wUnit.addCommand('pause', '500');	

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal('2')", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
